const faqItems = [
  {
    id: 1,
    question: "How do you source your seasonal ingredients?",
    answer: "At Casa Verde, we prioritize local and organic farms to ensure freshness and sustainability. Our chefs select the finest in-season produce each week, guaranteeing a taste of the finest terroir."
  },
  {
    id: 2,
    question: "Do you offer any dietary restrictions?",
    answer: "Absolutely! Our kitchen is equipped to handle gluten-free, dairy-free, and vegetarian options. Please inform our reservations team of any specific needs so we can prepare accordingly."
  },
  {
    id: 3,
    question: "What is your reservation policy?",
    answer: "We request a 24-hour cancellation notice for table reservations. No-shows will be charged a 50% fee. For parties of six or more, we kindly ask to be contacted directly."
  },
  {
    id: 4,
    question: "Is there an outdoor seating area?",
    answer: "Yes, we have a charming outdoor terrace with tables shaded by olive trees. Enjoy a glass of our house-made limoncello while dining al fresco."
  },
  {
    id: 5,
    question: "Do you offer wine pairings?",
    answer: "Absolutely! Our sommelier curates wine pairings that complement your dish of choice. Whether you're enjoying a wood-fired pizza or a classic pasta, we've got the perfect bottle to enhance your dining experience."
  }
];

export default function Faq() {
  const [expanded, setExpanded] = useState(0);
  const [loading, setLoading] = useState(false);

  const toggleAccordion = (index) => {
    if (expanded === index) {
      setExpanded(0);
    } else {
      setExpanded(index);
    }
  };

  return (
    <div className="w-full min-h-screen bg-[#faf6f0] text-stone-950 font-sans flex flex-col items-center justify-center p-6 sm:p-12">
