                {loading ? (
                  <div className="inline-flex items-center gap-2">
                    <span className="animate-pulse rounded-xl bg-white/10 px-3 py-1 text-sm text-slate-400" />
                    <span className="animate-pulse rounded-xl bg-white/10 px-3 py-1 text-sm text-slate-400" />
                    <span className="animate-pulse rounded-xl bg-white/10 px-3 py-1 text-sm text-slate-400" />
                  </div>
                ) : (
                  <p className="text-slate-400 max-w-md mt-4">
                    We're passionate about creating memorable dining experiences. Here are the answers to your questions.
                  </p>
                )}
              </p>
            </div>
          </div>
        </div>

        {/* Accordion Section */}
        <div className="w-full max-w-4xl space-y-4 sm:space-y-6">
          {faqItems.map((item) => (
            <div key={item.id} className="group relative overflow-hidden rounded-2xl bg-white/5 border border-white/10/30 p-6 transition-all duration-300 hover:shadow-2xl hover:scale-[1.01]">
              <div className="absolute inset-0 bg-white/5 backdrop-blur-xl" />
              <div className="relative flex items-start justify-between pb-8 sm:pb-10">
                <div className="flex items-center gap-3">
                  <div className="flex-none rounded-xl bg-white/10 p-3 text-slate-400 group-hover:text-indigo-400 transition-colors duration-200">
