                    {item.question}
                  </h3>
                </div>
                <div className="flex-none">
                  <button
                    type="button"
                    className="p-2 rounded-xl transition-transform duration-200 hover:scale-[1.02]"
                    onClick={() => toggleAccordion(item.id)}
                  >
                    <ChevronRight className={`w-5 h-5 transform transition-transform duration-200 ${expanded === item.id ? 'rotate-180' : ''}`} />
                  </button>
                </div>
              </div>
              {expanded === item.id && (
                <div className="relative -mt-10 -mb-10 pl-14 text-slate-400 group-hover:text-white transition-colors duration-200">
                  <div className="absolute left-6 top-5 flex items-center gap-2">
                    <ShieldCheck className="w-5 h-5 text-indigo-400" />
                    <Scale className="w-4 h-4 text-indigo-400" />
                  </div>
                  <p className="text-sm sm:text-base">{item.answer}</p>
