import React, { useState } from 'react';
import { Calendar, Clock, Sparkles, MapPin, UtensilsCrossed, ChefHat, Circle as Glass, CheckCircle2, ArrowRight } from 'lucide-react';

const initialForm = {
  name: '',
  email: '',
  guests: 4,
  date: '',
  time: '18:00',
};

export default function Reservations() {
  const [formData, setFormData] = useState(initialForm);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const validate = (values) => {
    const errors = {};
    if (!values.name.trim()) errors.name = 'Please enter your name';
    if (!values.email || !/^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i.test(values.email)) errors.email = 'Please enter a valid email';
    if (values.guests < 1 || values.guests > 10) errors.guests = 'Guests must be between 1 and 10';
    if (!values.date || !values.time) errors.date = 'Please select a date and time';
    return errors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const errors = validate(formData);
    if (Object.keys(errors).length === 0) {
      setIsSubmitting(true);
      setTimeout(() => {
        setIsSubmitting(false);
        setIsSuccess(true);
        setTimeout(() => setIsSuccess(false), 2000);
      }, 1200);
    } else {
      e.target.style.outline = '2px solid red';
    }
  };

  return (
    <section className="py-24 bg-white flex items-center justify-center min-h-[80vh]">
      <div className="max-w-xl w-full lg:max-w-2xl p-6 rounded-2xl bg-slate-950/10 border border-white/10 shadow-2xl backdrop-blur-xl">
        <div className="mb-8 flex flex-col lg:flex-row gap-6 items-start justify-between">
          <div className="flex flex-col gap-2">
            <h2 className="text-xl sm:text-2xl font-bold text-slate-100">Save a Table</h2>
            <p className="text-slate-400 text-sm max-w-md">We're a cozy trattoria. Make a reservation to enjoy our seasonal specials.</p>
          </div>
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-xl bg-amber-500/10 border border-amber-500/20 text-amber-400 text-xs font-medium">
              <Sparkles className="w-3.5 h-3.5 mr-1.5" />
              <span>Casa Verde</span>
            </div>
            <div className="p-1 rounded-xl bg-white/5 border border-white/10 text-white/50 text-xs">
              <Clock className="w-3.5 h-3.5 mr-1.5" />
              <span>Open Mon-Sun 11:00 - 23:00</span>
            </div>
          </div>
        </div>

        {isSuccess ? (
          <div className="py-8 text-center space-y-4">
            <div className="w-16 h-16 rounded-full bg-gradient-to-br from-indigo-500 via-purple-600 to-pink-500 border border-indigo-600/20 flex items-center justify-center mb-4 shadow-lg shadow-indigo-500/20">
              <CheckCircle2 className="w-8 h-8 text-white" />
            </div>
            <h3 className="text-xl font-semibold text-slate-200">Reservation Confirmed!</h3>
            <p className="text-slate-400 text-sm max-w-md mx-auto">We'll see you for your <span className="text-amber-400">{formData.date} at {formData.time}</span>. Enjoy your meal!</p>
            <button onClick={() => setIsSuccess(false)} className="bg-amber-600/10 hover:bg-amber-400/20 text-amber-300 rounded-lg border border-amber-500/10 p-3 font-semibold transition-all duration-300 text-sm">Reserve Another Table</button>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="relative group">
                <input 
                  type="text" 
                  placeholder="Name & Phone" 
                  className="w-full bg-slate-900/20 border border-slate-700/40 rounded-xl py-3 pl-4 pr-10 text-slate-100 focus:ring-2 focus:ring-amber-500/40 outline-none transition-all duration-300 placeholder:text-slate-500"
                  value={formData.name} 
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  required
                />
                <label className="absolute left-3 top-2.5 text-slate-400 group-hover:text-slate-300 transition-all duration-300 pointer-events-none">Full Name</label>
                {formData.name && <div className="absolute right-3 top-2.5 text-slate-400 group-hover:text-slate-300 transition-all duration-300 pointer-events-none">✓</div>}
              </div>
              <div className="relative group">
                <input 
