                  value={formData.email} 
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  required
                />
                <label className="absolute left-3 top-2.5 text-slate-400 group-hover:text-slate-300 transition-all duration-300 pointer-events-none">Email</label>
                {formData.email && <div className="absolute right-3 top-2.5 text-slate-400 group-hover:text-slate-300 transition-all duration-300 pointer-events-none">✓</div>}
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="relative group">
                <select 
                  className="w-full bg-slate-900/20 border border-slate-700/40 rounded-xl py-3 pl-4 pr-10 text-slate-100 focus:ring-2 focus:ring-amber-500/40 outline-none transition-all duration-300 placeholder:text-slate-500"
                  value={formData.guests}
                  onChange={(e) => setFormData({ ...formData, guests: parseInt(e.target.value) })}
                  required
                >
                  <option value="1">1 Guest</option>
                  <option value="2">2 Guests</option>
                  <option value="3">3 Guests</option>
                  <option value="4" selected>4 Guests</option>
                  <option value="5">5 Guests</option>
                  <option value="6">6 Guests</option>
                  <option value="7">7 Guests</option>
                  <option value="8">8 Guests</option>
                  <option value="9">9 Guests</option>
                  <option value="10">10 Guests</option>
                </select>
                <label className="absolute left-3 top-2.5 text-slate-400 group-hover:text-slate-300 transition-all duration-300 pointer-events-none">Party Size</label>
                {formData.guests && <div className="absolute right-3 top-2.5 text-slate-400 group-hover:text-slate-300 transition-all duration-300 pointer-events-none">✓</div>}
              </div>
              <div className="relative group">
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                    <Calendar className="w-4 h-4 text-slate-400" />
                  </div>
                  <input 
                    type="date" 
                    className="w-full bg-slate-900/20 border border-slate-700/40 rounded-xl py-3 pl-10 pr-4 text-slate-100 focus:ring-2 focus:ring-amber-500/40 outline-none transition-all duration-300 placeholder:text-slate-500"
                    value={formData.date}
                    onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                    required
                  />
                </div>
                <label className="absolute -top-3 left-3 text-slate-400 group-hover:text-slate-300 transition-all duration-300 pointer-events-none">Date</label>
                {formData.date && <div className="absolute -top-3 right-3 text-slate-400 group-hover:text-slate-300 transition-all duration-300 pointer-events-none">✓</div>}
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="relative group">
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                    <Clock className="w-4 h-4 text-slate-400" />
                  </div>
                  <input 
                    type="time" 
                    className="w-full bg-slate-900/20 border border-slate-700/40 rounded-xl py-3 pl-10 pr-4 text-slate-100 focus:ring-2 focus:ring-amber-500/40 outline-none transition-all duration-300 placeholder:text-slate-500"
                    value={formData.time}
                    onChange={(e) => setFormData({ ...formData, time: e.target.value })}
                    required
                  />
                </div>
                <label className="absolute -top-3 left-3 text-slate-400 group-hover:text-slate-300 transition-all duration-300 pointer-events-none">Time</label>
                {formData.time && <div className="absolute -top-3 right-3 text-slate-400 group-hover:text-slate-300 transition-all duration-300 pointer-events-none">✓</div>}
              </div>
              <div className="relative group">
                <select 
                  className="w-full bg-slate-900/20 border border-slate-700/40 rounded-xl py-3 pl-4 pr-10 text-slate-100 focus:ring-2 focus:ring-amber-500/40 outline-none transition-all duration-300 placeholder:text-slate-500"
                  value={formData.tableType}
                  onChange={(e) => setFormData({ ...formData, tableType: e.target.value })}
                  required
                >
                  <option value="">Table Type</option>
                  <option value="indoor">Indoor Seating</option>
                  <option value="outdoor">Outdoor Seating</option>
                </select>
                <label className="absolute left-3 top-2.5 text-slate-400 group-hover:text-slate-300 transition-all duration-300 pointer-events-none">Table Preference</label>
                {formData.tableType && <div className="absolute right-3 top-2.5 text-slate-400 group-hover:text-slate-300 transition-all duration-300 pointer-events-none">✓</div>}
              </div>
            </div>
            <div className="flex justify-end mt-6">
              <button 
                type="submit" 
                disabled={isSubmitting}
                className="inline-flex items-center gap-2 py-3 px-6 rounded-2xl bg-amber-600/10 text-amber-300 border border-amber-500/10 hover:bg-amber-400/10 transition-all duration-300 font-semibold text-sm"
              >
                {isSubmitting ? <div className="animate-spin text-slate-400"><span className="sr-only">Loading...</span></div> : <MapPin className="w-4 h-4" />} &nbsp;Save Table
              </button>
            </div>
          </form>
        )}
      </div>
    </section>
  );
}
